CREATE TABLE IF NOT EXISTS drivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,phone text,pin_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,plate text UNIQUE NOT NULL,current_odometer numeric(12,1) NOT NULL DEFAULT 0,rate_per_km numeric(12,2),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,route_date date NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','assigned','active','completed','cancelled')),optimize_by text NOT NULL DEFAULT 'distance',circular boolean NOT NULL DEFAULT false,driver_id uuid REFERENCES drivers(id),vehicle_id uuid REFERENCES vehicles(id),estimated_km numeric(12,2),actual_km numeric(12,1),started_at timestamptz,finished_at timestamptz,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS route_stops (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_id uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE,position integer NOT NULL,name text NOT NULL,address text NOT NULL,lat double precision NOT NULL,lng double precision NOT NULL,is_origin boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered')),delivered_at timestamptz,UNIQUE(route_id,position));
CREATE TABLE IF NOT EXISTS upload_objects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_key text UNIQUE NOT NULL,kind text NOT NULL,content_type text NOT NULL,size_bytes bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS odometer_readings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_id uuid NOT NULL REFERENCES routes(id),phase text NOT NULL CHECK(phase IN ('start','finish')),kilometers numeric(12,1) NOT NULL,photo_key text NOT NULL,lat double precision,lng double precision,recorded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(route_id,phase));
CREATE TABLE IF NOT EXISTS delivery_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid UNIQUE NOT NULL,route_id uuid NOT NULL REFERENCES routes(id),stop_id uuid NOT NULL REFERENCES route_stops(id),photo_key text NOT NULL,note text,lat double precision NOT NULL,lng double precision NOT NULL,delivered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS location_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid UNIQUE NOT NULL,route_id uuid NOT NULL REFERENCES routes(id),driver_id uuid NOT NULL REFERENCES drivers(id),lat double precision NOT NULL,lng double precision NOT NULL,accuracy double precision,recorded_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS location_route_time ON location_points(route_id,recorded_at DESC);
CREATE TABLE IF NOT EXISTS sync_operations (id uuid PRIMARY KEY,route_id uuid REFERENCES routes(id),kind text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY,actor_type text NOT NULL,actor_id text,action text NOT NULL,entity_type text NOT NULL,entity_id text,details jsonb,created_at timestamptz NOT NULL DEFAULT now());
